        dist = {start: 0}
        queue = [(start, -1)]
        while queue:
            v, p = queue.pop(0)
            for u in adj[v]:
                if u == p:
                    continue
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append((u, v))
                else:
                    # Found cycle
                    cycle_len = dist[v] + dist[u] + 1
                    if 3 <= cycle_len <= max_len:
                        # Reconstruct cycle
                        cycle = []
                        # Go from v back to common ancestor
                        curr = v
                        while curr != -1:
                            cycle.append(curr)
                            if curr == start:
                                break
                            curr = parent.get(curr, -1)
                        # Go from u back to common ancestor
