                            curr2 = parent.get(curr2, -1)
                        if curr2 in cycle:
                            idx = cycle.index(curr2)
                            cycle = cycle[:idx+1] + list(reversed(path2))
                        else:
                            cycle = cycle + list(reversed(path2))
                        if len(cycle) <= max_len + 1:
                            return cycle[:cycle_len]  # truncate to cycle_len
        # Reset
