import random
import itertools
from collections import deque

n = 14
girth_req = 8

def build_adj(edges):
    adj = {i: set() for i in range(n)}
    for i,j in edges:
        adj[i].add(j)
        adj[j].add(i)
    return adj

def shortest_cycle_bfs(adj):
    """Return length of shortest cycle, or None if acyclic."""
    best = None
    for start in range(n):
        parent = {start: -1}
        dist = {start: 0}
        q = deque([(start, -1)])
        while q:
            v, p = q.popleft()
            for u in adj[v]:
                if u == p:
                    continue
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    q.append((u, v))
                else:
                    cycle_len = dist[v] + dist[u] + 1
                    if best is None or cycle_len < best:
                        best = cycle_len
                        if best == 3:
                            return 3
    return best

def is_4_colorable(adj):
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        used = {colors[u] for u in adj[v] if colors[u] != -1}
        for c in range(4):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
        colors[v] = -1
        return False
    return backtrack(0)

def check_graph(edges):
    adj = build_adj(edges)
    g = shortest_cycle_bfs(adj)
    if g is None or g < girth_req:
        return False
    return is_4_colorable(adj)

