    random.shuffle(possible)

    for i, j in possible:
        # Check if adding (i,j) creates a cycle of length < 8
        # Use BFS to find shortest path between i and j
        # If dist(i,j) < 7 in current graph, adding edge creates cycle < 8
        parent = {i: -1}
        dist = {i: 0}
        q = deque([i])
        found = False
        while q and not found:
            v = q.popleft()
            if dist[v] >= 6:  # if distance already 6, adding edge gives cycle length 7
