            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    if u == j:
                        found = True
                        break
                    q.append(u)

        if not found:
            # Safe to add
            edges.add((i, j))
            adj[i].add(j)
            adj[j].add(i)

    if len(edges) > best_edges_count:
        if check_graph(edges):
            best_edges_count = len(edges)
            best_edges = edges.copy()
